Vercel AI SDK (Node) serverless proxy example:
// api/chat.js
import fetch from 'node-fetch'
export default async function handler(req, res){
  const r = await fetch(process.env.REDWOOD_API_URL + '/v1/generate', {headers:{'Authorization': `Bearer ${process.env.REDWOOD_API_KEY}`}, method:'POST', body: JSON.stringify(req.body)});
  // stream back to client
  r.body.pipe(res);
}
